 void options(JSONObject s){page("show-options","Identidade e permissões",s.optString("title"));get("/show/"+s.optInt("id")+"/options",r->{Switch download=new Switch(a);download.setText("Autorizar download dos episódios");download.setTextColor(WHITE);download.setChecked(r.optBoolean("allow_download"));download.setMinHeight(a.dp(56));a.body.addView(download);a.text(a.body,"Downloads ficam disponíveis dentro do Cineo. A desativação impede novos downloads, mas não recolhe arquivos já baixados.",12,MUTED);a.text(a.body,"ELENCO E EQUIPE · uma pessoa por linha, no formato Nome | Função",12,MUTED);EditText credits=a.field(a.body,"","Ex.: Ana Silva | Direção",false);credits.setSingleLine(false);credits.setMinLines(5);StringBuilder text=new StringBuilder();JSONArray items=r.optJSONArray("credits");if(items!=null)for(int i=0;i<items.length();i++){JSONObject c=items.optJSONObject(i);text.append(c.optString("name")).append(" | ").append(c.optString("role")).append('\n');}credits.setText(text);a.button(a.body,"Salvar opções",RED,()->a.safe(()->{JSONArray rows=new JSONArray();for(String line:credits.getText().toString().split("\n")){if(line.trim().isEmpty())continue;String[] pair=line.split("\\|",2);if(pair.length!=2)throw new IOException("Use Nome | Função em cada linha.");rows.put(a.obj("name",pair[0].trim(),"role",pair[1].trim()));}post("/show/"+s.optInt("id")+"/options",a.obj("allow_download",download.isChecked(),"credits",rows),ok->a.loadDetail(s.optInt("id"),"mine"));}));});}
