 void shared(){page("shared-productions","Projetos compartilhados","Sua equipe no Cineo.");get("/shared",r->{JSONArray rows=r.getJSONArray("items");if(rows.length()==0)a.empty(a.body,"film","Nenhum projeto compartilhado","Envie seu código de colaboração ao proprietário da produção.");for(int i=0;i<rows.length();i++){JSONObject s=rows.getJSONObject(i);a.title(a.body,s.optString("title"),20);a.button(a.body,"Conferir prévia",CARD,()->preview(s));if(s.optString("team_role").equals("editor")){a.button(a.body,"Enviar capítulos",RED,()->a.uploads.form(s));a.button(a.body,"Preparar elenco e equipe",CARD,()->options(s));}}});}
 void episode(JSONObject s,JSONObject e){page("episode-production-tools","Preparar capítulo",a.pro.episodeLabel(e));get("/episode/"+e.optInt("id")+"/settings",r->{JSONObject current=r.getJSONObject("episode"),job=r.optJSONObject("job");a.text(a.body,"Validação técnica: "+(job==null?current.optString("media_state"):job.optString("status"))+"\n"+(job==null?"":job.optString("message")),13,MUTED);EditText date=a.field(a.body,"PUBLICAR A PARTIR DE · HORÁRIO LOCAL","2026-12-01 19:00 · vazio = sem agendamento",false);if(!current.isNull("release_at")&&!current.optString("release_at").isEmpty())date.setText(java.time.Instant.parse(current.optString("release_at")).atZone(java.time.ZoneId.systemDefault()).format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm")));EditText start=number("ABERTURA · INÍCIO EM SEGUNDOS",current.optInt("intro_start")),end=number("ABERTURA · FIM EM SEGUNDOS",current.optInt("intro_end")),credits=number("CRÉDITOS · INÍCIO EM SEGUNDOS",current.optInt("credits_start"));a.text(a.body,"O agendamento só libera episódios aprovados. Abertura e créditos usam os intervalos definidos aqui.",13,MUTED);a.button(a.body,"Salvar agendamento e intervalos",RED,()->a.safe(()->{String at=date.getText().toString().trim();String iso=at.isEmpty()?"":java.time.LocalDateTime.parse(at,java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm")).atZone(java.time.ZoneId.systemDefault()).toInstant().toString();post("/episode/"+e.optInt("id")+"/settings",a.obj("release_at",iso,"intro_start",Integer.parseInt(start.getText().toString()),"intro_end",Integer.parseInt(end.getText().toString()),"credits_start",Integer.parseInt(credits.getText().toString())),ok->episode(s,e));}));a.button(a.body,"Validar / processar vídeo novamente",CARD,()->post("/episode/"+e.optInt("id")+"/reprocess",new JSONObject(),ok->episode(s,e)));a.button(a.body,"Adicionar áudio ou audiodescrição",CARD,()->trackForm(s,e));a.button(a.body,"Voltar aos capítulos",CARD,()->a.pro.studio(s));});}
