 boolean result(int req,int res,Intent intent){if(req!=44)return false;if(res!=Activity.RESULT_OK||intent==null||intent.getData()==null)return true;final android.net.Uri uri=intent.getData();final int page=a.generation;a.busy=true;a.loading.setVisibility(android.view.View.VISIBLE);a.io.execute(()->{try{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=a.getContentResolver().openInputStream(uri)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){if(out.size()+n>26214400)throw new IOException("Arquivo acima de 25 MB.");out.write(b,0,n);}}JSONObject result=a.request("POST","/v7/episode/"+trackEpisode+"/tracks",a.obj("label",trackLabel,"kind",trackKind,"video",android.util.Base64.encodeToString(out.toByteArray(),2)),a.token);a.runOnUiThread(()->{if(page!=a.generation)return;a.busy=false;a.loading.setVisibility(android.view.View.GONE);a.notice("Faixa adicionada. Confira a sincronização na prévia.",false);});}catch(Exception ex){a.runOnUiThread(()->{if(page!=a.generation)return;a.busy=false;a.loading.setVisibility(android.view.View.GONE);a.notice(ex.getMessage(),true);});}});return true;}
 void feature(JSONObject s){EditText order=new EditText(a);order.setInputType(2);order.setHint("Posição · vazio = retirar do carrossel");if(!s.isNull("featured_order"))order.setText(s.optString("featured_order"));new AlertDialog.Builder(a).setTitle("Destaque do catálogo").setView(order).setNegativeButton("Cancelar",null).setPositiveButton("Salvar",(d,n)->a.safe(()->post("/show/"+s.optInt("id")+"/options",a.obj("featured_order",order.getText().toString().trim().isEmpty()?JSONObject.NULL:Integer.parseInt(order.getText().toString())),ok->a.loadDetail(s.optInt("id"),"admin")))).show();}
 void insights(JSONObject s){page("retention-insights","Audiência e retenção",s.optString("title"));get("/show/"+s.optInt("id")+"/insights",r->{a.text(a.body,"Pessoas que chegaram a cada trecho do vídeo. As visitas são agregadas; nenhum espectador é identificado.",13,MUTED);JSONArray buckets=r.optJSONArray("buckets");int maximum=1;if(buckets!=null)for(int i=0;i<buckets.length();i++)maximum=Math.max(maximum,buckets.optJSONObject(i).optInt("viewers"));if(buckets!=null)for(int i=0;i<buckets.length();i++){JSONObject b=buckets.optJSONObject(i);a.text(a.body,(b.optInt("bucket")*10)+"–"+((b.optInt("bucket")+1)*10)+"% do vídeo · "+b.optInt("viewers")+" pessoa(s)",12,MUTED);ProgressBar bar=new ProgressBar(a,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(maximum);bar.setProgress(b.optInt("viewers"));bar.setProgressTintList(android.content.res.ColorStateList.valueOf(RED));a.body.addView(bar,new LinearLayout.LayoutParams(-1,a.dp(8)));a.gap(a.body,10);}JSONArray eps=r.optJSONArray("episodes");if(eps!=null)for(int i=0;i<eps.length();i++){JSONObject e=eps.getJSONObject(i);a.title(a.body,e.optString("title"),17);a.text(a.body,e.optInt("viewers")+" espectadores · "+e.optInt("completions")+" conclusões · "+e.optLong("watched_ms")/60000+" minutos assistidos",13,MUTED);}});}
 void correction(JSONObject s){EditText message=new EditText(a);message.setHint("Ex.: Áudio do episódio 2 corrigido");new AlertDialog.Builder(a).setTitle("Avisar quem acompanha").setMessage("O aviso aparecerá no Cineo para as pessoas que acompanham sua série ou seu perfil.").setView(message).setNegativeButton("Cancelar",null).setPositiveButton("Publicar aviso",(d,n)->a.safe(()->post("/show/"+s.optInt("id")+"/correction",a.obj("title",message.getText().toString()),r->Toast.makeText(a,"Aviso publicado.",0).show()))).show();}
 void appeals(){page("review-appeals",a.role.equals("admin")?"Recursos recebidos":"Meus recursos","Pedidos de nova análise.");get("/appeals",r->{JSONArray rows=r.getJSONArray("items");if(rows.length()==0)a.empty(a.body,"shield","Nenhum recurso","Recursos de reprovação e respostas aparecerão aqui.");for(int i=0;i<rows.length();i++){JSONObject appeal=rows.getJSONObject(i);a.title(a.body,"#"+appeal.optInt("id")+" · "+appeal.getJSONObject("show").optString("title"),18);a.text(a.body,appeal.optString("message"),14,MUTED);a.text(a.body,appeal.optString("reply").isEmpty()?"Aguardando resposta":appeal.optString("reply"),14,AMBER);if(a.role.equals("admin")){a.button(a.body,"Abrir produção",CARD,()->a.loadDetail(appeal.optInt("show_id"),"admin"));a.button(a.body,"Responder recurso",CARD,()->{EditText reply=new EditText(a);reply.setHint("Explique a decisão e os próximos passos");new AlertDialog.Builder(a).setTitle("Responder recurso").setView(reply).setNegativeButton("Cancelar",null).setPositiveButton("Responder",(d,n)->a.safe(()->post("/appeals",a.obj("id",appeal.optInt("id"),"reply",reply.getText().toString()),ok->appeals()))).show();});}}});}
