 void health(){page("platform-health","Saúde da plataforma","Consumo real do armazenamento e falhas recentes.");get("/health",r->{JSONArray storage=r.optJSONArray("storage");if(storage!=null)for(int i=0;i<storage.length();i++){JSONObject bucket=storage.getJSONObject(i);a.title(a.body,bucket.optString("bucket_id"),17);a.text(a.body,bucket.optLong("files")+" arquivo(s) · "+String.format(Locale.US,"%.1f MB",bucket.optLong("bytes")/1048576.0),13,MUTED);}a.text(a.body,"O tráfego e os limites do plano podem ser consultados no painel do serviço.",12,MUTED);a.button(a.body,"Abrir painel de consumo",CARD,()->a.startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://supabase.com/dashboard/project/njyjwcjrirqmbvsizqar/settings/usage"))));JSONArray jobs=r.optJSONArray("jobs");if(jobs!=null){a.title(a.body,"Processamento de vídeos",20);for(int i=0;i<jobs.length();i++){JSONObject j=jobs.getJSONObject(i);a.text(a.body,"Capítulo #"+j.optInt("episode_id")+" · "+j.optString("status")+"\n"+j.optString("message"),13,MUTED);}}JSONArray faults=r.optJSONArray("faults");if(faults!=null){a.title(a.body,"Falhas recentes",20);for(int i=0;i<faults.length();i++){JSONObject f=faults.getJSONObject(i);a.text(a.body,f.optString("kind")+" · "+f.optString("code")+" · "+a.pro.date(f.optString("created_at")),12,MUTED);}}a.button(a.body,"Atualizar diagnóstico",CARD,()->health());});}
